from bio_inspired_nanochat.kernels import presyn_fused
from bio_inspired_nanochat.perf_regression import PerfRegressionHarness, STANDARD_BENCHMARK_CONFIGS
from bio_inspired_nanochat.synaptic import SynapticConfig, build_presyn_state


def bit_equal(a, b):
    return torch.equal(a.contiguous().view(torch.uint8), b.contiguous().view(torch.uint8))


def state_values(state):
    for key in ("C", "BUF", "RRP", "RES", "PR", "CL", "E", "AMP"):
        yield state[key]
    yield from state["DELAY"]


def eager_pad(state, key_count, cfg):
    old = state["C"]
    shape = (*old.shape[:2], key_count - old.shape[2])
    initials = (
        0.0, 0.0, cfg.init_rrp, cfg.init_reserve, cfg.init_snare,
        cfg.init_clamp, cfg.init_energy, cfg.init_amp,
    )
    names = ("C", "BUF", "RRP", "RES", "PR", "CL", "E", "AMP")
    for key, value in zip(names, initials, strict=True):
        state[key] = torch.cat((state[key], torch.full(shape, value, device=old.device, dtype=old.dtype)), dim=2)
    state["DELAY"] = [torch.cat((plane, torch.zeros(shape, device=old.device, dtype=old.dtype)), dim=2)
                      for plane in state["DELAY"]]


def raw_parity(implementation):
    cases = 0
    for batch, heads, old_keys, new_keys in (
        (1, 4, 16, 17), (2, 3, 31, 32), (1, 4, 127, 128), (2, 3, 128, 129), (2, 3, 257, 259),
    ):
        for depth in (0, 1, 3, 5):
            config = SynapticConfig(
                endo_delay=depth, init_rrp=0.512345, init_reserve=16.34875,
                init_snare=-0.0, init_clamp=0.8625126, init_energy=0.9285, init_amp=1.2975,
            )
            state = build_presyn_state(batch, old_keys, heads, torch.device("cuda"), torch.float32, config)
            for item in state_values(state):
                item.uniform_(-0.1, 0.9)
            expected = {**state}
            live_inputs = [value.clone() for value in state_values(state)]
            old_views = list(state_values(state))
            eager_pad(expected, new_keys, config)
            assert implementation(state, new_keys, config)
            for plane, (a, b) in enumerate(zip(state_values(state), state_values(expected), strict=True)):
                assert bit_equal(a, b), (batch, heads, old_keys, new_keys, depth, plane,
                                         a[0, 0, -1].view(torch.int32).item(),
                                         b[0, 0, -1].view(torch.int32).item())
            assert all(bit_equal(a, b) for a, b in zip(old_views, live_inputs, strict=True))
            cases += 1
    config = SynapticConfig()
    state = build_presyn_state(2, 8, 2, torch.device("cuda"), torch.float32, config)
    state["C"] = state["C"].transpose(0, 1)
    assert not implementation(state, 9, config)
    assert state["C"].shape == (2, 2, 8)
    return cases


def trajectories(implementation):
    comparisons = []
    args = [(1, 4, 16, 40, 3), (2, 2, 29, 7, 0), (2, 2, 123, 9, 3), (1, 4, 250, 10, 1)]
    for seed, (batch, kv_heads, prompt, steps, delay) in enumerate(args, 19628):
        torch.manual_seed(seed)
        config = GPTSynapticConfig(
            sequence_len=prompt + steps, n_layer=2, n_head=4, n_kv_head=kv_heads, n_embd=64,
            vocab_size=128, syn_cfg=SynapticConfig(native_presyn=True, native_genetics=True, endo_delay=delay),
        )
        model = GPTSynaptic(config).to("cuda").eval()
        model.reset_sequence_state()
        engine = Engine(model, tokenizer=None)
        tokens = torch.randint(0, config.vocab_size, (batch, prompt + steps), device="cuda")
        old = KVCache(batch, kv_heads, prompt + steps, 16, 2)
        candidate = KVCache(batch, kv_heads, prompt + steps, 16, 2)
        engine._forward(tokens[:, :prompt], old)
        engine._forward(tokens[:, :prompt], candidate)
        calls = 0

        def count_pad(*args, **kwargs):
            nonlocal calls
            used = implementation(*args, **kwargs)
            calls += used
            return used

        for pos in range(prompt, prompt + steps):
            presyn_fused.pad_live_decode_state = lambda *_args, **_kwargs: False
            expected, _ = engine._forward(tokens[:, pos:pos+1], old)
            presyn_fused.pad_live_decode_state = count_pad
            actual, _ = engine._forward(tokens[:, pos:pos+1], candidate)
            assert bit_equal(expected, actual), (seed, pos, "logits")
            assert old.pos == candidate.pos == pos + 1
            assert bit_equal(old.kv_cache[:, :, :, :, :old.pos], candidate.kv_cache[:, :, :, :, :old.pos])
            for layer, (a, b) in enumerate(zip(old.presyn_state, candidate.presyn_state, strict=True)):
                assert all(bit_equal(x, y) for x, y in zip(state_values(a), state_values(b), strict=True)), (seed, pos, layer)
        assert calls == 2 * steps, (calls, steps)
        comparisons.append({"batch": batch, "kv_heads": kv_heads, "prompt": prompt, "steps": steps,
                            "delay_depth": delay, "exact_pad_calls": calls})
    return comparisons


def bench(implementation, mode):
    harness = PerfRegressionHarness()
    standard, syn = [replace(cfg, device="cuda") for cfg in STANDARD_BENCHMARK_CONFIGS if cfg.mode=="decode"]
    output = []

    def run(phase, seed):
        torch.manual_seed(seed)
        presyn_fused.pad_live_decode_state = (implementation if phase == "candidate"
                                               else lambda *_args, **_kwargs: False)
        cfg = standard if phase == "vanilla" else syn
        if mode == "profile":
            cfg = replace(cfg, name=f"cached_decode_{phase}")
        return harness.run_benchmark(cfg, nvtx=mode=="profile")

    if mode == "profile":
        for phase in ("vanilla", "eager", "candidate"):
            output.append(asdict(run(phase, 20004)))
        return output
    for phase in ("vanilla", "eager", "candidate"):
        run(phase, 20019)
    for index, seed in enumerate(range(20020, 20028)):
        order = ["vanilla", "eager", "candidate"][::(-1 if index % 2 else 1)]
        results = {phase: run(phase, seed) for phase in order}
        comparisons = {phase: asdict(harness.evaluate_budget_gates([results["vanilla"], results[phase]])[0])
                       for phase in ("eager", "candidate")}
        output.append({"seed": seed, "order": order, "comparisons": comparisons,
                       "peak_memory_mb": {phase: results[phase].peak_memory_mb for phase in results}})
    return output


def main():
    mode, out = sys.argv[1:]
    implementation = presyn_fused.pad_live_decode_state
    try:
        if mode == "parity":
            with torch.inference_mode():
                result = {"raw_cases": raw_parity(implementation), "traces": trajectories(implementation)}
        elif mode == "profile":
            result = {"benchmarks": bench(implementation, mode)}
        else:
            runs = bench(implementation, mode)
            result = {
                "runs": runs,
                "median_paired_improvement": statistics.median(
                    1.0 - row["comparisons"]["candidate"]["slowdown_ratio"] /
                    row["comparisons"]["eager"]["slowdown_ratio"] for row in runs
                ),
                "median_ratios": {
                    phase: statistics.median(row["comparisons"][phase]["slowdown_ratio"] for row in runs)
                    for phase in ("eager", "candidate")
                },
                "gate_passes": {
                    phase: sum(row["comparisons"][phase]["passed"] for row in runs)
                    for phase in ("eager", "candidate")
                },
            }
    finally:
        presyn_fused.pad_live_decode_state = implementation
    with Path(out).open("x", encoding="utf-8") as stream:
        json.dump(result, stream, sort_keys=True, indent=2, allow_nan=False)
        stream.write("\n")
    print(json.dumps({k:v for k,v in result.items() if k!="runs"}, sort_keys=True))


if __name__ == "__main__":
    main()
